// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListBackends List the model backends. Secrets show their last 4 characters only (SDD §14.1).
	// (GET /admin/backends)
	ListBackends(w http.ResponseWriter, r *http.Request)
	// CreateBackend Add a model backend (REQ-100).
	// (POST /admin/backends)
	CreateBackend(w http.ResponseWriter, r *http.Request)
	// DeleteBackend Delete a backend that no role uses.
	// (DELETE /admin/backends/{backendId})
	DeleteBackend(w http.ResponseWriter, r *http.Request, backendId BackendId)
	// UpdateBackend Change a backend. Leave the secret out to keep the stored one.
	// (PUT /admin/backends/{backendId})
	UpdateBackend(w http.ResponseWriter, r *http.Request, backendId BackendId)
	// TestBackend Send one short call to a backend and model, to check the setup.
	// (POST /admin/backends/{backendId}/test)
	TestBackend(w http.ResponseWriter, r *http.Request, backendId BackendId)
	// GetBudget Get this month's token budget and use (REQ-104).
	// (GET /admin/budget)
	GetBudget(w http.ResponseWriter, r *http.Request)
	// SetBudget Set the monthly token limit. No limit means no budget.
	// (PUT /admin/budget)
	SetBudget(w http.ResponseWriter, r *http.Request)
	// ListMCPConnections List the MCP connections (REQ-112).
	// (GET /admin/mcp)
	ListMCPConnections(w http.ResponseWriter, r *http.Request)
	// CreateMCPConnection Add an MCP connection.
	// (POST /admin/mcp)
	CreateMCPConnection(w http.ResponseWriter, r *http.Request)
	// DeleteMCPConnection Delete an MCP connection.
	// (DELETE /admin/mcp/{connectionId})
	DeleteMCPConnection(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// UpdateMCPConnection Change an MCP connection. Leave the secret out to keep the stored one.
	// (PUT /admin/mcp/{connectionId})
	UpdateMCPConnection(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// ListMCPTools Connect and list the server's tools, to choose the allowlist.
	// (GET /admin/mcp/{connectionId}/tools)
	ListMCPTools(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// ListPresets List the agent CLI presets and whether each CLI is installed (REQ-102).
	// (GET /admin/presets)
	ListPresets(w http.ResponseWriter, r *http.Request)
	// ListRoles List the roles and their backend and model (REQ-101).
	// (GET /admin/roles)
	ListRoles(w http.ResponseWriter, r *http.Request)
	// UnassignRole Remove a role's assignment.
	// (DELETE /admin/roles/{role})
	UnassignRole(w http.ResponseWriter, r *http.Request, role RoleName)
	// AssignRole Assign a backend and model to a role.
	// (PUT /admin/roles/{role})
	AssignRole(w http.ResponseWriter, r *http.Request, role RoleName)
	// ListBundles List bundles, and the folders that look like bundles but are not valid.
	// (GET /bundles)
	ListBundles(w http.ResponseWriter, r *http.Request, params ListBundlesParams)
	// CreateBundle Create a bundle from a profile's template (REQ-016).
	// (POST /bundles)
	CreateBundle(w http.ResponseWriter, r *http.Request)
	// ImportBundle Import a bundle from a .md file, a .zip file, or pasted markdown.
	// (POST /bundles/import)
	ImportBundle(w http.ResponseWriter, r *http.Request)
	// GetBundle Get one bundle.
	// (GET /bundles/{bundleId})
	GetBundle(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// ListAssumptions List the sentences of the current main doc that start with "Assumption:" (REQ-033).
	// (GET /bundles/{bundleId}/assumptions)
	ListAssumptions(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// DiffVersions Compare two versions of a bundle, by file and by section of the main doc (REQ-006).
	// (GET /bundles/{bundleId}/diff)
	DiffVersions(w http.ResponseWriter, r *http.Request, bundleId BundleId, params DiffVersionsParams)
	// ExportBundle Download a bundle version as a .zip file. The default is the current version (REQ-008).
	// (GET /bundles/{bundleId}/export)
	ExportBundle(w http.ResponseWriter, r *http.Request, bundleId BundleId, params ExportBundleParams)
	// DeleteFile Delete a file. Creates a version (REQ-005).
	// (DELETE /bundles/{bundleId}/files)
	DeleteFile(w http.ResponseWriter, r *http.Request, bundleId BundleId, params DeleteFileParams)
	// ListFiles List the files of a bundle version. The default is the current version.
	// (GET /bundles/{bundleId}/files)
	ListFiles(w http.ResponseWriter, r *http.Request, bundleId BundleId, params ListFilesParams)
	// GetFileContent Get the bytes of one file in a bundle version. The default is the current version.
	// (GET /bundles/{bundleId}/files/content)
	GetFileContent(w http.ResponseWriter, r *http.Request, bundleId BundleId, params GetFileContentParams)
	// PutFileContent Create or replace a file. Creates a version when the content changed (REQ-005).
	// (PUT /bundles/{bundleId}/files/content)
	PutFileContent(w http.ResponseWriter, r *http.Request, bundleId BundleId, params PutFileContentParams)
	// RenameFile Rename or move a file inside the bundle. Creates a version (REQ-005).
	// (POST /bundles/{bundleId}/files/rename)
	RenameFile(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// ListRuns List the review runs of a bundle, newest first.
	// (GET /bundles/{bundleId}/runs)
	ListRuns(w http.ResponseWriter, r *http.Request, bundleId BundleId, params ListRunsParams)
	// StartRun Start a full review of the current version (REQ-020). Lint runs on its own on every save.
	// (POST /bundles/{bundleId}/runs)
	StartRun(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// EstimateRun Estimate the tokens and cost of a full review before it starts (REQ-104).
	// (GET /bundles/{bundleId}/runs/estimate)
	EstimateRun(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// ListVersions List the versions of a bundle, newest first.
	// (GET /bundles/{bundleId}/versions)
	ListVersions(w http.ResponseWriter, r *http.Request, bundleId BundleId, params ListVersionsParams)
	// GetMeta Get the server version and mode.
	// (GET /meta)
	GetMeta(w http.ResponseWriter, r *http.Request)
	// ListProfiles List the profiles, with their current versions.
	// (GET /profiles)
	ListProfiles(w http.ResponseWriter, r *http.Request)
	// RenderMarkdown Render markdown to HTML. Each block carries its source position (DEC-017).
	// (POST /render)
	RenderMarkdown(w http.ResponseWriter, r *http.Request)
	// GetRun Get one review run and its verdict.
	// (GET /runs/{runId})
	GetRun(w http.ResponseWriter, r *http.Request, runId RunId)
	// ListClaims List a run's factual claims and their labels (REQ-031).
	// (GET /runs/{runId}/claims)
	ListClaims(w http.ResponseWriter, r *http.Request, runId RunId)
	// RunEvents Follow a run's progress by stage, as server-sent events (REQ-026).
	// (GET /runs/{runId}/events)
	RunEvents(w http.ResponseWriter, r *http.Request, runId RunId)
	// ListFindings List the findings of a run, in document order.
	// (GET /runs/{runId}/findings)
	ListFindings(w http.ResponseWriter, r *http.Request, runId RunId)
	// ListQuestions List a run's build questions, reader answers, and results (REQ-040 to REQ-046).
	// (GET /runs/{runId}/questions)
	ListQuestions(w http.ResponseWriter, r *http.Request, runId RunId)
}

